select user_id
from trade_order
where pay_time is not null
  and order_status in ('PAY_SUCCESS', 'GROUP_SETTLED', 'DEAL_DONE')

  and pay_time >= #{startTime}


  and pay_time <= #{endTime}

group by user_id
having count(1) >= #{minOrderCount}

select user_id
from trade_order
where pay_time is not null
  and order_status in ('PAY_SUCCESS', 'GROUP_SETTLED', 'DEAL_DONE')

  and pay_time >= #{startTime}


  and pay_time <= #{endTime}

group by user_id
having sum(pay_amount) >= #{minPayAmount}

select distinct user_id
from trade_order
where pay_time is not null
  and order_status in ('PAY_SUCCESS', 'GROUP_SETTLED', 'DEAL_DONE')

  and pay_time >= #{startTime}


  and pay_time <= #{endTime}

select count(1)
from crowd_tags_detail
where tag_id = #{tagId}

select count(1) > 0
from crowd_tags_detail
where tag_id = #{tagId}
  and user_id = #{userId}

mapper.update:
update crowd_tags_job
set status = #{status},
    update_time = now()
where tag_id = #{tagId}
  and batch_id = #{batchId}
